import time

class Timer:
    def __enter__(self):
        self.start = time.time()
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        elapsed = time.time() - self.start
        print(f'Elapsed: {elapsed:.3f}s')

with Timer():
    sum(range(1_000_000))
